#!/bin/sh
# Rebuild the schema snapshots used by migration tests.
#   sqlite/v1.db          schema 0001 + seed_v1.sql (timestamps as epoch ms, booleans as 0/1)
#   sqlite/v2.db          v1 + migration 0002 + seed_v2.sql
#   postgres/v1_seed.sql  seed_v1.sql for Postgres (TIMESTAMPTZ, true/false); load after 0001_init.sql
#   postgres/v2_seed.sql  seed_v2.sql for Postgres; load after 0001, v1_seed.sql and 0002
#   sqlite/v3.db          v2 + migration 0003 + seed_v3.sql
#   postgres/v3_seed.sql  seed_v3.sql for Postgres; load after the v2 files and 0003
#   sqlite/v4.db          v3 + migration 0004 + seed_v4.sql
#   postgres/v4_seed.sql  seed_v4.sql for Postgres; load after the v3 files and 0004
# Released snapshots are never edited: `./build.sh` only writes snapshots that don't exist yet.
# `./build.sh --force <version>` rebuilds one unreleased version on purpose.
# Add vN here whenever a new migration ships.
set -eu
cd "$(dirname "$0")"
ROOT=../..
SQLITE_MIG=$ROOT/crates/storage-sqlite/migrations
FORCE=""
[ "${1:-}" = "--force" ] && FORCE=${2:?"--force needs a version"}

sqlite_seed() { sed -e 's/:TS(\([0-9]*\))/\1/g' -e 's/:TRUE/1/g' -e 's/:FALSE/0/g' "$1"; }
pg_seed() { sed -e "s/:TS(\([0-9]*\))/to_timestamp(\1 \/ 1000.0)/g" -e 's/:TRUE/true/g' -e 's/:FALSE/false/g' "$1"; }
wanted() { [ ! -e "$1" ] || [ "$FORCE" = "$2" ]; }

if wanted sqlite/v1.db 1; then
  rm -f sqlite/v1.db
  sqlite3 sqlite/v1.db < "$SQLITE_MIG/0001_init.sql"
  sqlite_seed seed_v1.sql | sqlite3 sqlite/v1.db
  sqlite3 sqlite/v1.db 'PRAGMA user_version = 1; VACUUM;'
  echo "built sqlite/v1.db"
fi

if wanted postgres/v1_seed.sql 1; then
  {
    echo '-- Generated by testdata/db/build.sh from seed_v1.sql. Load after storage-postgres 0001_init.sql.'
    pg_seed seed_v1.sql
    echo "SELECT setval('hosts_id_seq', (SELECT max(id) FROM hosts));"
    echo "SELECT setval('events_id_seq', (SELECT max(id) FROM events));"
  } > postgres/v1_seed.sql
  echo "built postgres/v1_seed.sql"
fi

if wanted sqlite/v2.db 2; then
  rm -f sqlite/v2.db
  sqlite3 sqlite/v2.db < "$SQLITE_MIG/0001_init.sql"
  sqlite_seed seed_v1.sql | sqlite3 sqlite/v2.db
  sqlite3 sqlite/v2.db < "$SQLITE_MIG/0002_modules.sql"
  sqlite_seed seed_v2.sql | sqlite3 sqlite/v2.db
  sqlite3 sqlite/v2.db 'PRAGMA user_version = 2; VACUUM;'
  echo "built sqlite/v2.db"
fi

if wanted postgres/v2_seed.sql 2; then
  {
    echo '-- Generated by testdata/db/build.sh from seed_v2.sql. Load after storage-postgres 0001_init.sql,'
    echo '-- v1_seed.sql and 0002_modules.sql.'
    pg_seed seed_v2.sql
    echo "SELECT setval('events_id_seq', (SELECT max(id) FROM events));"
    echo "SELECT setval('metrics_id_seq', (SELECT max(id) FROM metrics));"
  } > postgres/v2_seed.sql
  echo "built postgres/v2_seed.sql"
fi

if wanted sqlite/v3.db 3; then
  rm -f sqlite/v3.db
  sqlite3 sqlite/v3.db < "$SQLITE_MIG/0001_init.sql"
  sqlite_seed seed_v1.sql | sqlite3 sqlite/v3.db
  sqlite3 sqlite/v3.db < "$SQLITE_MIG/0002_modules.sql"
  sqlite_seed seed_v2.sql | sqlite3 sqlite/v3.db
  sqlite3 sqlite/v3.db < "$SQLITE_MIG/0003_processes.sql"
  sqlite_seed seed_v3.sql | sqlite3 sqlite/v3.db
  sqlite3 sqlite/v3.db 'PRAGMA user_version = 3; VACUUM;'
  echo "built sqlite/v3.db"
fi

if wanted postgres/v3_seed.sql 3; then
  {
    echo '-- Generated by testdata/db/build.sh from seed_v3.sql. Load after storage-postgres 0001_init.sql,'
    echo '-- v1_seed.sql, 0002_modules.sql, v2_seed.sql and 0003_processes.sql.'
    pg_seed seed_v3.sql
    echo "SELECT setval('hosts_id_seq', (SELECT max(id) FROM hosts));"
    echo "SELECT setval('events_id_seq', (SELECT max(id) FROM events));"
  } > postgres/v3_seed.sql
  echo "built postgres/v3_seed.sql"
fi

if wanted sqlite/v4.db 4; then
  rm -f sqlite/v4.db
  sqlite3 sqlite/v4.db < "$SQLITE_MIG/0001_init.sql"
  sqlite_seed seed_v1.sql | sqlite3 sqlite/v4.db
  sqlite3 sqlite/v4.db < "$SQLITE_MIG/0002_modules.sql"
  sqlite_seed seed_v2.sql | sqlite3 sqlite/v4.db
  sqlite3 sqlite/v4.db < "$SQLITE_MIG/0003_processes.sql"
  sqlite_seed seed_v3.sql | sqlite3 sqlite/v4.db
  sqlite3 sqlite/v4.db < "$SQLITE_MIG/0004_hours.sql"
  sqlite_seed seed_v4.sql | sqlite3 sqlite/v4.db
  sqlite3 sqlite/v4.db 'PRAGMA user_version = 4; VACUUM;'
  echo "built sqlite/v4.db"
fi

if wanted postgres/v4_seed.sql 4; then
  {
    echo '-- Generated by testdata/db/build.sh from seed_v4.sql. Load after storage-postgres 0001_init.sql,'
    echo '-- v1_seed.sql, 0002_modules.sql, v2_seed.sql, 0003_processes.sql, v3_seed.sql and 0004_hours.sql.'
    pg_seed seed_v4.sql
  } > postgres/v4_seed.sql
  echo "built postgres/v4_seed.sql"
fi
